"""完成スライドのブラウザ閲覧版と、公開用の監視要約を作成する。"""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2]
FOLDER=ROOT/'materials/slides/第04回_角測量'
slides=json.loads((ROOT/'notes/session04/kai2/slides_part1.json').read_text(encoding='utf-8'))
payload=json.dumps([dict(id=d['id'],title=d['title'],notes=d['notes'],section=d['section']) for d in slides],ensure_ascii=False).replace('</','<\/')
template='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>角測量 回2｜授業スライド</title><style>body{margin:0;color:#182b33;background:#eef2f3;font:17px/1.6 "Yu Gothic",Meiryo,sans-serif}header,footer{padding:12px 22px;background:white}header{display:flex;gap:16px;align-items:center;flex-wrap:wrap}h1{font-size:19px;margin:0}button,select{font:inherit;padding:7px 12px;max-width:100%;border:1px solid #78918f;background:white;color:#166b68}button{cursor:pointer}button:disabled{color:#888;cursor:default}:focus-visible{outline:3px solid #b65b00;outline-offset:3px}main{max-width:1280px;margin:12px auto}img{width:100%;height:auto;display:block;background:white}details{padding:16px 24px;background:white}summary{cursor:pointer;color:#166b68}#notes{white-space:pre-line}a{color:#166b68}.hint{font-size:14px}select{width:430px}@media print{header,footer,details{display:none}body{background:white}main{margin:0}}</style><header><h1>第4回 角測量「回2」</h1><button id="prev" aria-label="前のスライド">← 前</button><button id="next" aria-label="次のスライド">次 →</button><select id="jump" aria-label="ページ選択"></select><label><input id="appendix" type="checkbox">付録を含める</label><button id="full">全画面</button></header><main><img id="slide" src="preview_回2/slide-01.png" alt="角測量の表紙"><details><summary>発表者ノート</summary><p id="notes"></p></details></main><footer><span id="count" aria-live="polite"></span><p class="hint">← → またはPageUp / PageDownで移動。付録は解答を含みます。画像フォルダー preview_回2 を一緒に保存してください。</p><a href="slides_回2.pptx">PowerPoint</a> ／ <a href="slides_回2.pdf">本編PDF</a> ／ <a href="explanation_回2.html">解説HTML</a></footer><script>const data=PAYLOAD;let i=0;const $=s=>document.getElementById(s);function list(){let n=$('appendix').checked?63:50;$('jump').replaceChildren(...data.slice(0,n).map((d,k)=>{let o=document.createElement('option');o.value=k;o.textContent=d.id+'　'+d.title;return o}));i=Math.min(i,n-1);show()}function show(){let n=$('appendix').checked?63:50,d=data[i];$('slide').src='preview_回2/slide-'+String(d.id).padStart(2,'0')+'.png';$('slide').alt=d.section+'：'+d.title;$('notes').textContent=d.notes;$('jump').value=i;$('count').textContent=(i+1)+' / '+n+'　'+d.section;$('prev').disabled=i===0;$('next').disabled=i===n-1}function step(v){i=Math.max(0,Math.min(($('appendix').checked?63:50)-1,i+v));show()}$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('jump').onchange=e=>{i=Number(e.target.value);show()};$('appendix').onchange=list;$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){$('count').textContent='全画面にできません。ブラウザの全画面操作を利用してください。'}};addEventListener('keydown',e=>{if(['SELECT','INPUT','BUTTON','SUMMARY'].includes(document.activeElement.tagName))return;if(['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();step(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();step(-1)}});list();</script></html>'''
(FOLDER/'slides_回2.html').write_text(template.replace('PAYLOAD',payload),encoding='utf-8')
monitor=ROOT/'notes/session04/monitor.jsonl'
if monitor.exists():
    rows=[]
    for l in monitor.read_text(encoding='utf-8').splitlines():
        v=json.loads(l);rows.append({'checked_at':v['checked_at'],'claude_session':v.get('claude_session')})
    (ROOT/'notes/session04/kai2/monitor_summary.json').write_text(json.dumps({'interval_seconds':300,'stopped_after_review_and_dialogue':True,'checks':rows},ensure_ascii=False,indent=2),encoding='utf-8')
print('閲覧HTMLと監視要約を作成')
